{
  "status": "SUPPORTED",
  "task_summary": "Distribute refreshment settings to two locations and reposition the entertainment control for accessibility.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds refreshments for a person",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["cup", "plate", "glass", "napkin"],
      "required_properties": ["holds liquid or solid food"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["remote control", "handheld controller"],
      "required_properties": ["operates television functions"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Supports placed items",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["table", "desk", "stand", "shelf"],
      "required_properties": ["flat", "stable", "supports weight"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_on_surface",
        "relation": "refreshment_setting is placed on surface",
        "participant_roles": ["refreshment_setting", "surface"]
      ,
      "required": true
      },
      {
        "id": "control_on_surface",
        "relation": "entertainment_control is placed on surface",
        "participant_roles": ["entertainment_control", "surface"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "distribute_refreshments",
        "operation": "Separate refreshment settings to distinct locations",
        "participant_roles": ["refreshment_setting", "surface"],
        "operation_count": 1
      },
      {
        "id": "relocate_control",
        "operation": "Move entertainment control to a central accessible surface",
        "participant_roles": ["entertainment_control", "surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "white plates", "visual_description": "two white circular dishes on the long table"},
        {"label": "red cups", "visual_description": "two red cylindrical containers on the long table"}
      ],
      "entertainment_control": [
        {"label": "remote", "visual_description": "black rectangular device on the long table"}
      ],
      "surface": [
        {"label": "long table", "visual_description": "wooden desk in foreground with items on top"},
        {"label": "console table", "visual_description": "low wooden stand under the television"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "long_table_storage",
        "label": "long table",
        "visual_description": "wooden surface with visible knobs or handles underneath",
        "reason": "Has storage compartments that could contain additional refreshment items or supplies"
      },
      {
        "id": "console_table_storage",
        "label": "console table",
        "visual_description": "wooden stand under TV with visible knobs or handles",
        "reason": "Has storage compartments that could contain additional supplies or the entertainment control"
      }
    ],
    "inspection_order": [
      "long table",
      "console table"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
  }
